import{_ as e,o as t,c as r,a0 as o}from"./chunks/framework.jwovEGr5.js";const n="/assets/%E5%A4%AA%E5%B9%B3%E6%B4%8B%E5%B2%9B%E9%93%BE.D0_j7sC7.png",u=JSON.parse('{"title":"中国战略空间和国家安全分析","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"中山大学/新生课程/国家安全.md","filePath":"中山大学/新生课程/国家安全.md"}'),p={name:"中山大学/新生课程/国家安全.md"};function s(i,a,l,h,d,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="中国战略空间和国家安全分析" tabindex="-1">中国战略空间和国家安全分析 <a class="header-anchor" href="#中国战略空间和国家安全分析" aria-label="Permalink to &quot;中国战略空间和国家安全分析&quot;">​</a></h1><p>课程时间：2026.8.20 16:30~17:30</p><p>主讲：许少民</p><h2 id="国家安全的本质" tabindex="-1">国家安全的本质 <a class="header-anchor" href="#国家安全的本质" aria-label="Permalink to &quot;国家安全的本质&quot;">​</a></h2><p>国家安全是指国家政权、主权、统一和领土完整、人民福祉、经济社会可持续发展和国家其他重大利益<code>相对</code>处于没有危险和不受<code>内外</code>威胁的状态，以及保障持续安全状态的能力。</p><h3 id="两种不同内涵的安全" tabindex="-1">两种不同内涵的安全 <a class="header-anchor" href="#两种不同内涵的安全" aria-label="Permalink to &quot;两种不同内涵的安全&quot;">​</a></h3><p><strong>消极安全</strong></p><p>零和博弈甚至负和博弈</p><p><strong>积极安全</strong></p><p>正和博弈</p><h2 id="国家安全的地缘基础" tabindex="-1">国家安全的地缘基础 <a class="header-anchor" href="#国家安全的地缘基础" aria-label="Permalink to &quot;国家安全的地缘基础&quot;">​</a></h2><h3 id="美国战略空间" tabindex="-1">美国战略空间 <a class="header-anchor" href="#美国战略空间" aria-label="Permalink to &quot;美国战略空间&quot;">​</a></h3><p><strong>太平洋岛链</strong></p><p><img src="'+n+'" alt="太平洋岛链" width="400px"></p><h3 id="中国战略空间-从平面到立体" tabindex="-1">中国战略空间，从平面到立体 <a class="header-anchor" href="#中国战略空间-从平面到立体" aria-label="Permalink to &quot;中国战略空间，从平面到立体&quot;">​</a></h3><p><strong>平面</strong></p><p>第一环：中国本土</p><p>第二环：陆上和海上邻国（14个陆上邻国，6个海上邻国）</p><p>第三环：六大区域</p><p>第四环：欧洲、非洲、中东、美洲</p><p><strong>立体</strong></p><p>第五环：极地、深海、太空、网络</p><h2 id="中国战略空间划分与外交布局" tabindex="-1">中国战略空间划分与外交布局 <a class="header-anchor" href="#中国战略空间划分与外交布局" aria-label="Permalink to &quot;中国战略空间划分与外交布局&quot;">​</a></h2><p><strong>战略空间（地缘圈层，同心圆结构）</strong></p><p>分四大次区域：东北亚、东南亚、南亚、中亚</p><p><strong>新时代中国外交总布局</strong></p><p>四大支柱：大国是关键、周边是首要、发展中国家是基础、多边是重要舞台</p><h2 id="一带一路-倡议的战略空间想象及其对中美-战略竞争-的意义" tabindex="-1">“一带一路”倡议的战略空间想象及其对中美“战略竞争”的意义 <a class="header-anchor" href="#一带一路-倡议的战略空间想象及其对中美-战略竞争-的意义" aria-label="Permalink to &quot;“一带一路”倡议的战略空间想象及其对中美“战略竞争”的意义&quot;">​</a></h2><p>形成陆海内外联动、东西双向互济的开放新格局</p><p><strong>“一带一路”倡议的两大战略意义</strong></p><ol><li>以空间换时间：陆海统筹，反制美国印太战略</li><li>地缘经济竞争消解地缘政治竞争</li></ol><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><p>国家安全日：4.15</p>',33)])])}const m=e(p,[["render",s]]);export{u as __pageData,m as default};
